tafsir_text:
وقوله :  {  وَلَوْ يُعَجِّلُ اللَّهُ لِلناسِ الشَّرَّ اسْتِعْجَالَهُمْ بِالْخَيْرِ }

يقول :  لو أجيب الناس في دعاء أحدهم على ابنه وشبهه بقولهم .  أماتك الله ،  ولعنك الله ،  وأخزاك الله لهلكوا .  و( استعجالهم ) منصوب بوقوع الفعل :  ( يعجل ) ؛  كما تقول :  قد ضربت اليوم ضربتك ،  والمعنى :  ضربت كضربتك وليس المعنى ها هنا كقولك :  ضربت ضربا ؛  لأن ضربا لا تضمر الكاف فيه ؛  لأنك لم تشبهه بشيء ،  وإنما شبهت ضربك بضرب غيرك فحسنت فيه الكاف .

وقوله :  {  لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ } ويقرأ :  ( لقَضَى إليهم أجلهم ) .  ومثله {  فيمسك التي قَضَى عليها الموتَ } و( قُضِى عليها الموتُ ) .

وقوله :  {  يا أَيُّها الناسُ إِنَّما بَغْيُكُمْ على أَنفُسِكُمْ }

إن شئت جعلت خبر ( البغي ) في قوله ( على أنفسكم ) ثم تنصب ( متاعَ الحياةِ الدنيا ) كقولك :  مُتْعَةً في الحياة الدنيا .  ويصلح الرفع ها هنا على الاستئناف ؛ كما قال {  لم يلبثوا إِلا ساعة من نهارٍ بلاغ } أي ذلك ( بلاغ ) وذلك ( متاع الحياةِ الدنيا ) وإن شئت جعلت الخبر في المتاع .  وهو وجه الكلام .

{  لِّلَّذِينَ أَحْسَنُواْ الْحُسْنَى وَزِيَادَةٌ وَلاَ يَرْهَقُ وُجُوهَهُمْ قَتَرٌ وَلاَ ذِلَّةٌ أولئك أَصْحابُ الْجَنَّةِ هُمْ فِيها خَالِدُونَ }

وقوله :  {  لِّلَّذِينَ أَحْسَنُواْ الْحُسْنَى }

في موضع رفع .  يقال إن الحسنى الحَسَنة . ( وزيادة ) حدّثنا محمد قال حدّثنا الفرّاء قال حدثني أبو الأحوص سلاّم بن سُلَيم عن أَبى إسحاق السَبِيعيّ عن رجل عن أبى بكر الصدِّيق رحمه الله قال :  للذين أحسنوا الحسنى وزيادة :  النظر إلى وجه الرب تبارك وتعالى .  ويقال ( للذين أحسنوا الحسنى ) يريد حَسَنة مثل حسناتهم ( وزيادة ) زيادة التضعيف كقوله {  فله عَشْرُ أَمثالها } .

وقوله :  {  وَالَّذِينَ كَسَبُواْ السَّيِّئَاتِ جَزَاء سَيِّئَةٍ بِمِثْلِها .  .  .  }

رفعت الجزاء بإضمار ( لهم ) كأنك قلت :  فلهم جزاء السيئة بمثلها ؛  كما قال {  ففِدية مِن صِيامٍ } و {  فصيام ثلاثةِ أيام في الحج } والمعنى :  فعليه صيام ثلاثة أيام ،  وعليه فدية .  وإن شئت رفعت الجزاء بالباء في قوله :  {  جَزَاء سَيِّئَةٍ بِمِثْلِها } والأوّل أعجب إلىَّ .

وقوله :  {  كَأَنَّما أُغْشِيَتْ وُجُوهُهُمْ قِطَعاً } و ( قطْعا ) .  والقِطَع قراءة العامَّة .  وهي في مصحف أبى {  كأنما يَغْشَى وجوهَهم قِطْع من الليل مظلم } فهذه حجة لمن قرأ بالتخفيف .  وإن شئت جعلت المظلم وأنت تقول قِطْع قطعا من الليل ،  وإن شئت جعلت المظلم نعتا للقطع ،  فإذا قلت قطعا كان قطعا من الليل خاصة .  والقطع ظلمة آخر الليل {  فأَسِر بأهلك بقطع من الليل } .

وقوله :  {  هُنالِكَ تَبْلُواْ كُلُّ نَفْسٍ }

قرأها عبد الله بن مسعود :  ( تتلو ) بالتاء .  معناها - والله أعلم - :  تتلو أي يقرأ كلُّ نفس عملها في كتاب ؛  كقوله :  {  ونخرِج له يوم القِيامةِ كِتابا يلقاه منشورا } وقوله {  فأما من أُوتِى كِتابه بِيمينِه } .  وقوله {  اقرأ كِتابك } قوّة لقراءة عبد الله .  قرأها مجاهد ( تبلو كل نفسٍ ما أسلفت ) أي تَخْبره وتراه .  وكل حَسَن .  حدّثنا محمد قال حدّثني الفرّاء قال حدثنا محمد بن عبد العزيز التيمي عن مُغيرةَ عن مجاهد أنه قرأ ( تبلو ) بالباء .  وقال الفرّاء :  حدّثنى بعض المشيخة عن الكلبىّ عن أبى صالح عن ابن عباس :  ( تبلو ) تَخْبر ،  وكذلك قرأها ابن عباس .

وقوله {  وَرُدُّواْ إِلَى اللَّهِ مَوْلاَهُمُ الْحَقِّ } ( الحقِّ ) تجعله من صفات الله تبارك وتعالى .  وإن شئت جعلته نصبا تريد :  ردّ إلى الله حقا .  وإن شئت :  مولاهم حقا .

وقوله تعالى :  {  كَذَلِكَ حَقَّتْ كَلِمَةُ رَبِّكَ .  .  .  }

وقد يقرأ ( كلمة ربِك ) و ( كلمات ربك ) .  قراءة أهل المدينة على الجمع .

وقوله :  {  على الَّذِينَ فَسَقُواْ أَنَّهُمْ لاَ يُؤْمِنُونَ } :  حَقَّت عليهم لأنهم لا يؤمنون ،  أو بأنهم لا يؤمنون ،  فيكون موضعها نصبا إذا ألقيت الخافض .  ولو كسرت فقلت :   " إنهم "  كان صوابا على الابتداء .  وكذلك قوله {  آمنت أنه لا إِله إِلا الذي آمنتْ بِه بنو إِسرائيل } وكسرها أصحاب عبد الله على الابتداء .

وقوله :  {  قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُواْ }

هذه قراءة العامة .  وقد ذكر عن زيد بن ثابت أنه قرأ ( فبذلك فلتفرحوا ) أي يا أصحاب محمد ،  بالتاء .

وقوله :  {  هُوَ خَيْرٌ مِّما يَجْمَعُونَ } :  يَجْمع الكفار .  وقَوّى قولَ زيد أنها في قراءة أبىّ ( فبذلك فافرحوا ) وهو البناء الذي خُلِق للأمر إذا واجهْتَ به أو لم تواجِه ؛  إلا أن العرب حذفت اللام من فعل المأمور المواجَه لكثرة الأمر خاصَّة في كلامهم ؛  فحذفوا ؛  اللام كما حذفوا التاء من الفعل .  وأنت تعلم أن الجازم أو الناصب لا يقعان إلا على الفعل الذي أوّله الياء والتاء والنون والألف .  فلما حُذِفت التاء ذهبت باللام وأحدثت الألف في قولك :  اضرب وافرح ؛  لأن الضاد ساكنة فلم يستقم أن يُستأنف بحرف ساكن ،  فأدخلوا ألفا خفيفة يقع بها الابتداء ؛  كما قال :  ( ادّارَكوا ) .  ( واثّاقَلْتُم ) .  وكان الكسائيّ يعيب قولهم ( فلتفرحوا ) لأنه وجده قليلا فجعله عيبا ،  وهو الأصل .  ولقد سمعت عن النبىّ صلى الله عليه وسلم أنه قال في بعض المشاهد ( لتأخذوا مصافّكم ) يريد به خذوا مصافّكم .

وقوله :  {  وَما تَكُونُ فِي شَأْنٍ وَما تَتْلُواْ مِنْهُ مِن قُرْآنٍ وَلاَ تَعْمَلُونَ مِنْ عَمَلٍ إِلاَّ كُنا عَلَيْكُمْ شُهُوداً }

يقول :  الله تبارك وتعالى شاهد على كل شيء .  ( وما ) ها هنا جحد لا موضع لها .  وهي كقوله {  ما يكون مِن نَّجْوَى ثَلاَثَةٍ إِلا هُوَ رابِعهم } يقول :  إلا هو شاهدهم .

{  وَما يَعْزُبُ عَن رَّبِّكَ مِن مِّثْقَالِ ذَرَّةٍ فِي الأَرْضِ وَلاَ فِي السَّماء وَلاَ أَصْغَرَ مِن ذلك وَلا أَكْبَرَ } و( أصغرُ وأكبرُ ) .  فمن نصبهما فإنما يريد الخفض :  يُتْبعهما المثقال أو الذرّة .  ومن رفعهما أتبعهما معنى المثقال ؛  لأنك لو ألقيت من المثقال ( مِن ) كان رفعا .  وهو كقولك :  ما أتاني من أحد عاقلٍ وعاقلٌ .  وكذلك قوله {  ما لكم مِن إِلهٍ غيرِه } .

وقوله :  {  أَلا إِنَّ أَوْلِيَاء اللَّهِ لاَ خَوْفٌ عَلَيْهِمْ وَلاَ هُمْ يَحْزَنُونَ .  الَّذِينَ آمَنُواْ وَكَانُواْ يَتَّقُونَ }

( الذين ) في موضع رفع ؛  لأنه نعت جاء بعد خبر إنْ ؛  كما قال {  إِن ذلِكَ لَحَقٌّ تخاصُمُ أَهْلِ النارِ } وكما قال {  قُلْ إِنَّ رَبِّى يَقْذِفُ بِالحَقِّ عَلاَّمُ الغُيُوبِ } والنصب في كل ذلك جائز على الإتباع للاسم الأوّل وعلى تكرير ( إنّ ) .

وإنما رفعت العرب النعوت إذا جاءت بعد الأفاعيل في ( إنّ ) لأنهم رأوا الفعل مرفوعا ،  فتوهّموا أن صاحبه مرفوع في المعنى - لأنهم لم يجدوا في تصريف المنصوب اسما منصوبا وفعله مرفوع - فرفعوا النعت .  وكان الكسائي يقول :  جعلته - يعنى النعت - تابعا للاسم المضمر في الفعل ؛  وهو خطأ وليس بجائز ؛  لأن ( الظريف ) وما أشبهه أسماء ظاهرة ،  ولا يكون الظاهر نعتا لمكنىّ إلا ما كان مثل نفسه وأنفسهم ،  وأجمعين ،  وكلهم ؛  لأن هذه إنما تكون أطرافا لأواخر الكلام ؛  لا يقال مررت بأجمعين ،  كما يقال مررت بالظريف .

وقوله :  {  لَهُمُ الْبُشْرَى فِي الْحَياةِ الدُّنْيَا }

وذكر أن البشرى في الحياة الدنيا الرؤيا الصالحة يراها المسلم أو ترى له ،  وفي الآخرة الجنة .  وقد يكون قوله :  {  لَهُمُ الْبُشْرَى } ما بشّرهم به في كتابه من موعوده ،  فقال {  ويبشِر المؤمِنِين الذِين يعملون الصالِحاتِ } في كثير من القرآن .

ثم قال لَهُمُ {  لاَ تَبْدِيلَ لِكَلِماتِ اللَّهِ } أي لا خُلْف لوعد الله .

وقوله :  {  قَالَ مُوسَى أَتقُولُونَ لِلْحَقِّ لَما جَاءكُمْ أَسِحْرٌ هَذَا }

يقول القائل :  كيف أدخل ألف الاستفهام في قوله ( أسحِر هذا ) وهم قد قالوا ( هذا سحر ) بغير استفهام ؟

قلت :  قد يكون هذا من قولهم على أنه سحر عندهم وإن استفهموا ؛  كما ترى الرجل تأتيه الجائزة فيقول :  أحقّ هذا ؟  وهو يعلم أنه حقّ لا شكّ فيه .  فهذا وجه .  ويكون أن تزيد الألف في قولهم وإن كانوا لم يقولوها ،  فيخرج الكلام على لفظه وإن كانوا لم يتكلّموا به ؛  كما يقول الرجل :  فلان أعلم منك ،  فيقول المتكلم :  أقلتَ أحدٌ أعلم بذا منّى ؟  فكأنه هو القائل :  أأحد أعلم بهذا منى .  ويكون على أن تجعل القول بمنزلة الصلة لأنه فضل في الكلام ؛  ألا ترى أنك تقول الرجل :  أتقول عندك مال ؟  فيكفيك من قوله أن تقول :  ألك مال ؟  فالمعنى قائم ظهرَ القولُ أوْ لم يظهر .

وقوله :  {  أَجِئْتَنا لِتَلْفِتَنا }

اللفت :  الصرف ؛  تقول :  ما لفتك عن فلان ؟  أي ما صرفك عنه .

ويقول القائل :  كيف قالوا ( وتكون لكما الكِبرياء في الأرض ) فإنّ النبي صلى الله عليه وسلم إذا صُدِّق صارت مقاليدُ أُمّته ومُلْكُهم إليه ،  فقالوه على مُلْك ملوكهم من التكبر .

وقوله :  {  فَما آمَنَ لِمُوسَى إِلاَّ ذُرِّيَّةٌ مِّن قَوْمِهِ }

ففسَّر المفسرون الذرِّيَّة :  القليل .  وكانوا - فيما بلغنا - سبعين أهل بيت .  وإنما سموا الذرّية لأن آباءهم كانوا من القِبط وأمهاتهم كنّ من بنى إسرائيل ،  فسموا الذرّية ؛  كما قيل لأولاد أهل فارس الذين سقطوا إلى اليمن فسمَّوا ذراريَّهم الأبناء ؛  لأن أمهاتهم من غير جنس آبائهم .

وقوله :  {  على خَوْفٍ مِّن فِرْعَوْنَ وَمَلَئِهِمْ } ،  وإنما قال ( وملئهم ) وفرعون واحد لان الملِك إذا ذُكر بخوف أو بسفر أو قدوم من سفر ذهب الوَهْم إليه وإلى من معه ؛  ألا ترى أنك تقول :  قدم الخليفة فكثر الناس ،  تريد :  بمن معه ،  وقدم فغلت الأسعار ؛  لأنك تنوى بقدومه قدوم من معه .  وقد يكون أن تريد بفرعون آل فرعون وتحذف الآل فيجوز ؛  كما قال {  واسأل القرية } تريد أهل القرية والله أعلم .  ومن ذلك قوله :  {  يأيها النبي إذا طلقتم النساء فطلقوهن لعدتهن } .
